:root {
    --color-button-fab: #0BA5EC    ;
    --color-button-gradient: #084F8A;
    --color-button-fab-text: #FFF1DA;
    --tg-img: url('/assets/img/fab/tg.png');
    --fb-img: url('/assets/img/fab/fb.png');
    --email-img: url('/assets/img/fab/ml.png');
}

    /* Floating Button */
    .chat-button {
      position: fixed;
      bottom: 20px;
      right: 20px;
      background-color: var(--color-button-fab);
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      justify-content: center;
      align-items: center;
      cursor: pointer;
      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
      transition: transform 0.3s ease;
  z-index: 100000;
    }

    .chat-button:hover {
      transform: scale(1.1);
    }

    /* Chat button icon */
    .chat-button i {
      color: white;
      font-size: 20px;
  z-index: 100000;
    }

    /* Popup Menu */
    .popup-menu {
      position: fixed;
      bottom: 75px;
      right: 20px;
      background-color: white;
      border-radius: 20px;
      box-shadow: 0 4px 10px rgba(0, 0, 0, 0.15);
      display: none;
      flex-direction: column;
      opacity: 0;
      transition: opacity 0.5s ease; /* Fade effect */
  z-index: 10000;
    }

    .popup-menu.active {
      display: flex;
      opacity: 1;
    }

    /* Menu items */
    .menu-item {
      display: flex;
      align-items: center;
      padding: 10px 25px;
      cursor: pointer;
      transition: background-color 0.2s;
    }

    .menu-item:hover {
      background-color: #f1f1f1;
      border-radius: 20px;
    }

.menu-item a {
  display: flex;
  align-items: center;
  text-decoration: none;
  color: inherit;
}

.menu-item a:before {
  content: '';
  width: 35px;
  height: 35px;
  margin-right: 10px;
  display: inline-block;
  background-size: cover;
}

.tg-link:before {
  background-image: var(--tg-img);
}

.fb-link:before {
  background-image: var(--fb-img);
}

.email-link:before {
  background-image: var(--email-img);
}

/* Сообщение рядом с кнопкой чата */
.message {
  position: fixed;
  bottom: 30px; /* Позиция от нижнего края */
  right: 100px; /* Позиция от правого края, чтобы находиться рядом с кнопкой чата */
  background: linear-gradient(135deg, var(--color-button-fab), var(--color-button-gradient));
  color: var(--color-button-fab-text); /* Цвет текста */
  padding: 15px 20px; /* Увеличенные отступы для лучшего пространства */
  border-radius: 20px; /* Более закругленные углы */
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
  display: none; /* Скрыто по умолчанию */
  transition: opacity 0.5s ease, transform 0.3s ease; /* Эффект появления и небольшая трансформация */
  font-size: 16px; /* Увеличенный размер шрифта */
  text-align: center; /* Центрир

  btnPrev.addEventListener('click', (e) => { e.preventDefault(); move('prev'); });
  btnNext.addEventListener('click', (e) => { e.preventDefault(); move('next'); });

  // --- SWIPE / DRAG ---
  track.style.willChange = 'transform';
  viewport.style.touchAction = 'pan-y'; // вертикальный скролл ок

  let dragging = false;
  let startX = 0;
  let startY = 0;
  let startTranslate = 0;
  let moved = 0;
  let lockedAxis = null; // 'x' | 'y' | null
  let isSwipe = false;   // ВАЖНО: был ли реальный горизонтальный свайп

  const onDown = (e) => {
    if (e.isPrimary === false) return;

    // если начали на ссылке/кнопке — не стартуем drag (ссылка приоритетнее)
    if (e.target && e.target.closest && e.target.closest('a, button')) {
      dragging = false;
      lockedAxis = null;
      moved = 0;
      isSwipe = false;
      return;
    }

    dragging = true;
    lockedAxis = null;
    moved = 0;
    isSwipe = false;

    startX = e.clientX;
    startY = e.clientY;
    startTranslate = currentX;

    setTransition(false);
    viewport.setPointerCapture?.(e.pointerId);
  };

  const onMove = (e) => {
    if (!dragging) return;

    const dx = e.clientX - startX;
    const dy = e.clientY - startY;

    if (!lockedAxis) {
      if (Math.abs(dx) < 6 && Math.abs(dy) < 6) return;
      lockedAxis = Math.abs(dx) > Math.abs(dy) ? 'x' : 'y';
    }

    if (lockedAxis === 'y') {
      // даём странице скроллиться
      dragging = false;
      setTransition(true);
      return;
    }

    // горизонтальный свайп — блокируем нативный скролл
    e.preventDefault();

    moved = dx;
    if (Math.abs(dx) > 10) isSwipe = true; // ВАЖНО: фиксируем факт свайпа

    applyTranslate(startTranslate + dx);
  };

  const onUp = () => {
    if (!dragging) return;
    dragging = false;

    const step = getStep();
    const threshold = Math.min(80, step * 0.25);

    if (Math.abs(moved) > threshold) {
      index += (moved < 0 ? 1 : -1);
    }

    render();

    // ВАЖНО: сброс moved, чтобы клики после свайпа не были заблокированы навсегда
    moved = 0;
    // isSwipe сбросится на следующем onDown
  };

  viewport.addEventListener('pointerdown', onDown, { passive: true });
  viewport.addEventListener('pointermove', onMove, { passive: false });
  viewport.addEventListener('pointerup', onUp, { passive: true });
  viewport.addEventListener('pointercancel', onUp, { passive: true });
  viewport.addEventListener('lostpointercapture', onUp, { passive: true });

  // блокируем клик ТОЛЬКО если реально был горизонтальный свайп
  viewport.addEventListener('click', (e) => {
    if (isSwipe) {
      e.preventDefault();
      e.stopPropagation();
    }
  }, true);

  // ресайз
  let raf = 0;
  window.addEventListener('resize', () => {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      setTransition(false);
      clampIndex();
      render();
    });
  });

  render();
})();
</script>



    <script>
    /* MOB SLIDER (1 card per view) */
    (function () {
    const qs = (s, r = document) => r.querySelector(s);
    const qsa = (s, r = document) => Array.from(r.querySelectorAll(s));

    function initMobSlider(root) {
        const viewport = qs('.mob-slider__slider', root);
        if (!viewport) return;

        const btns = qsa('.mob-slider__btn', root);
        const btnPrev = btns[0] || null;
        const btnNext = btns[1] || null;
        if (!btnPrev || !btnNext) return;

        // wrap items into track (без правок HTML руками)
        let track = qs('.mob-slider__track', viewport);
        if (!track) {
        const items = qsa(':scope > .promo__item', viewport);
        track = document.createElement('div');
        track.className = 'mob-slider__track';
        items.forEach((it) => track.appendChild(it));
        viewport.appendChild(track);
        }

        const items = qsa('.promo__item', track);
        if (!items.length) return;

        let idx = 0;

        const getGap = () => {
        const cs = window.getComputedStyle(track);
        const g = parseFloat(cs.columnGap || cs.gap || '0');
        return Number.isFinite(g) ? g : 0;
        };

        const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

        const maxIndex = () => items.length - 1;

        const apply = (animate = true) => {
        idx = clamp(idx, 0, maxIndex());

        const gap = getGap();
        const slideW = viewport.clientWidth; // promo__item = 100% viewport
        const x = -idx * (slideW + gap);

        if (!animate) track.style.transition = 'none';
        track.style.transform = `translate3d(${x}px,0,0)`;
        if (!animate) {
            // force reflow and вернуть transition
            track.offsetHeight; // eslint-disable-line no-unused-expressions
            track.style.transition = '';
        }

        btnPrev.classList.toggle('is-disabled', idx === 0);
        btnNext.classList.toggle('is-disabled', idx === maxIndex());
        };

        const go = (dir) => {
        idx += dir;
        apply(true);
        };

        btnPrev.addEventListener('click', (e) => { e.preventDefault(); go(-1); });
        btnNext.addEventListener('click', (e) => { e.preventDefault(); go(1); });

        // swipe (touch)
        let startX = 0;
        let startY = 0;
        let isTouching = false;

        viewport.addEventListener('touchstart', (e) => {
        if (!e.touches || !e.touches[0]) return;
        isTouching = true;
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
        }, { passive: true });

        viewport.addEventListener('touchend', (e) => {
        if (!isTouching) return;
        isTouching = false;

        const t = (e.changedTouches && e.changedTouches[0]) ? e.changedTouches[0] : null;
        if (!t) return;

        const dx = t.clientX - startX;
        const dy = t.clientY - startY;

        // если вертикальный скролл — не трогаем
        if (Math.abs(dy) > Math.abs(dx)) return;

        const threshold = Math.max(40, viewport.clientWidth * 0.12);
        if (dx > threshold) go(-1);
        else if (dx < -threshold) go(1);
        }, { passive: true });

        // resize -> пересчитать translate (без дерганья)
        const ro = new ResizeObserver(() => apply(false));
        ro.observe(viewport);

        apply(false);
    }

    qsa('.mob-slider').forEach(initMobSlider);
    })();
    </script>

    <script>
    (function () {
    const qs = (s, r=document) => r.querySelector(s);

    const lockScroll = (on) => {
        document.documentElement.classList.toggle('no-scroll', on);
        document.body.classList.toggle('no-scroll', on);
    };

    let lastTrigger = null;

    const openModal = (id, triggerEl) => {
        const modal = document.getElementById(id);
        if (!modal) return;

        lastTrigger = triggerEl || null;

        modal.classList.add('is-open');
        modal.setAttribute('aria-hidden', 'false');
        lockScroll(true);

        if (triggerEl) triggerEl.setAttribute('aria-expanded', 'true');

        // фокус в диалог
        const focusTarget =
        qs('.disc-modal__close', modal) ||
        qs('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])', modal);

        if (focusTarget) focusTarget.focus({ preventScroll: true });
    };

    const closeModal = (modal) => {
        if (!modal) return;

        modal.classList.remove('is-open');
        modal.setAttribute('aria-hidden', 'true');
        lockScroll(false);

        const id = modal.id;
        // обновить aria-expanded у всех триггеров этой модалки
        document.querySelectorAll(`[data-modal-open="${CSS.escape(id)}"]`)
        .forEach(btn => btn.setAttribute('aria-expanded', 'false'));

        if (lastTrigger) {
        lastTrigger.focus({ preventScroll: true });
        lastTrigger = null;
        }
    };

    document.addEventListener('click', (e) => {
        const openBtn = e.target.closest('[data-modal-open]');
        if (openBtn) {
        e.preventDefault();
        const id = openBtn.getAttribute('data-modal-open');
        openModal(id, openBtn);
        return;
        }

        const closeBtn = e.target.closest('[data-modal-close]');
        if (closeBtn) {
        e.preventDefault();
        const modal = closeBtn.closest('.disc-modal');
        closeModal(modal);
        }
    });

    document.addEventListener('keydown', (e) => {
        if (e.key !== 'Escape') return;
        const modal = qs('.disc-modal.is-open');
        if (modal) closeModal(modal);
    });
    })();
    </script>

    <script>
document.addEventListener('DOMContentLoaded', () => {
  const items = document.querySelectorAll('.faq__acc');
  if (!items.length) return;

  const openClass = 'is-open';

  function closeItem(item) {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    item.classList.remove(openClass);

    // фиксируем текущую высоту и анимируем в 0
    content.style.height = content.scrollHeight + 'px';
    content.offsetHeight; // reflow
    content.style.height = '0px';
  }

  function openItem(item) {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    item.classList.add(openClass);

    // если было auto — вернем в пиксели перед анимацией
    content.style.height = content.scrollHeight + 'px';

    content.addEventListener('transitionend', function onEnd(e) {
      if (e.propertyName !== 'height') return;
      if (item.classList.contains(openClass)) content.style.height = 'auto';
      content.removeEventListener('transitionend', onEnd);
    });
  }

  // init: поддержка твоего класса faq__acc-content-active
  items.forEach(item => {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    content.style.overflow = 'hidden';
    content.style.transition = 'height 250ms ease';

    const isActive = content.classList.contains('faq__acc-content-active');
    if (isActive) {
      item.classList.add(openClass);
      content.style.height = 'auto';
    } else {
      content.style.height = '0px';
    }
  });

  // click handler: один открыт, остальные закрываем
  items.forEach(item => {
    item.addEventListener('click', (e) => {
      e.preventDefault();

      const isOpen = item.classList.contains(openClass);

      items.forEach(i => { if (i !== item) closeItem(i); });

      if (isOpen) closeItem(item);
      else openItem(item);
    });
  });
});
</script>

    <!-- scripts end -->

    
</body>
</html>

