(function(){
  'use strict';

  var TOTAL_STEPS = 8;
  var modal = document.getElementById('wizardmodal');
  var rootEl = document.getElementById('rootwizard');
  var tabsEl = document.getElementById('discTabs');
  var progressEl = document.getElementById('discProgress');
  var panesEl = document.querySelectorAll('[data-step-pane]');
  var resultEl = document.getElementById('discResult');
  var scoreEl = document.getElementById('discScore');
  var backBtn = document.querySelector('[data-disc-prev]');
  var nextBtn = document.querySelector('[data-disc-next]');
  var finishBtn = document.querySelector('[data-disc-finish]');
  var redoBtn = document.querySelector('[data-disc-redo]');
  var linkInput = document.getElementById('discLink');

  var step = 0;
  var finished = false;

  /* initial order of every list (snapshot) */
  var initialOrder = {};
  document.querySelectorAll('.disc-list').forEach(function(list){
    initialOrder[list.id] = Array.prototype.slice.call(list.children);
  });

  /* ---------- modal open / close ---------- */
  function setModalOpen(open){
    modal.classList.toggle('is-open', open);
    modal.setAttribute('aria-hidden', open ? 'false' : 'true');
    document.documentElement.classList.toggle('no-scroll', open);
    document.body.classList.toggle('no-scroll', open);
  }
  function setModalClosed(){ setModalOpen(false); }

  Array.prototype.slice.call(document.querySelectorAll('[data-modal-open="wizardmodal"]'))
    .forEach(function(btn){
      btn.addEventListener('click', function(){
        resetTest();
        setModalOpen(true);
        var first = document.querySelector('#tab1 .disc-item');
        if(first) first.focus();
      });
    });

  Array.prototype.slice.call(document.querySelectorAll('[data-disc-close]'))
    .forEach(function(el){ el.addEventListener('click', setModalClosed); });

  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape' && modal.classList.contains('is-open')) setModalClosed();
  });

  /* ---------- step navigation ---------- */
  function setStep(n){
    step = n;
    finished = false;
    showPanes();
    Array.prototype.slice.call(tabsEl).forEach(function(tab, i){
      tab.classList.toggle('is-active', i === step);
      tab.setAttribute('aria-selected', i === step ? 'true' : 'false');
    });
    backBtn.disabled = (step === 0);
    nextBtn.hidden = (step === TOTAL_STEPS - 1);
    finishBtn.hidden = (step !== TOTAL_STEPS - 1);
    progressEl.style.width = (step / TOTAL_STEPS * 100) + '%';
  }
  function showPanes(){
    Array.prototype.slice.call(panesEl).forEach(function(pane){
      pane.classList.toggle('is-active', parseInt(pane.getAttribute('data-step-pane'), 10) === step);
    });
    tabsEl.hidden = false;
    rootEl.hidden = false;
    resultEl.hidden = true;
  }
  function showResult(){
    var sc = computeScore();
    scoreEl.textContent = 'D:' + sc.d + ', I:' + sc.i + ', S:' + sc.s + ', C:' + sc.c;
    tabsEl.hidden = true;
    rootEl.hidden = true;
    resultEl.hidden = false;
    linkInput.value = location.href;
    finished = true;
  }
  function resetTest(){
    document.querySelectorAll('.disc-list').forEach(function(list){
      var orig = initialOrder[list.id];
      if(!orig) return;
      Array.prototype.slice.call(orig).forEach(function(el){
        list.appendChild(el);
      });
    });
    document.querySelectorAll('.disc-item--drag').forEach(function(el){
      el.classList.remove('disc-item--drag');
      el.style.transform = '';
    });
    finished = false;
    linkInput.value = '';
    setStep(0);
  }

  nextBtn.addEventListener('click', function(){
    if(step < TOTAL_STEPS - 1) setStep(step + 1);
  });
  backBtn.addEventListener('click', function(){
    if(step > 0) setStep(step - 1);
  });
  Array.prototype.slice.call(tabsEl).forEach(function(tab, i){
    tab.addEventListener('click', function(){
      if(!finished) setStep(i);
    });
  });
  finishBtn.addEventListener('click', showResult);
  if(redoBtn) redoBtn.addEventListener('click', function(){ resetTest(); setModalOpen(true); });

  /* ---------- score ----------
     Each list: 4 items ranked from 1st to 4th -> 4 / 3 / 2 / 1 points
     to the item's DISC type (data-type). 24 lists -> total 240. */
  function computeScore(){
    var sc = { d: 0, i: 0, s: 0, c: 0 };
    document.querySelectorAll('.disc-list').forEach(function(list){
      var items = Array.prototype.slice.call(list.children);
      items.forEach(function(item, pos){
        var t = item.getAttribute('data-type');
        if(t && t in sc) sc[t] += (4 - pos);
      });
    });
    return sc;
  }

  /* ---------- drag & drop (Pointer Events; works for mouse + touch) ---------- */
  var drag = null;

  function onPointerDown(e, item){
    if(e.pointerType === 'mouse' && e.button !== 0) return;
    if(drag) return;
    item.setPointerCapture(e.pointerId);
    var r = item.getBoundingClientRect();
    drag = {
      item: item,
      list: item.closest('.disc-list'),
      offset: e.clientY - r.top,
      y: e.clientY,
      started: false
    };
  }
  function alignItem(clientY){
    var item = drag.item;
    item.style.transform = 'translate3d(0, 0, 0)';
    var slotTop = item.getBoundingClientRect().top;
    item.style.transform = 'translate3d(0, ' + (clientY - drag.offset - slotTop) + 'px, 0)';
  }
  function onPointerMove(e){
    if(!drag) return;
    if(!drag.started){
      if(Math.abs(e.clientY - drag.y) < 6){ return; }
      drag.started = true;
      drag.item.classList.add('disc-item--drag');
    }
    alignItem(e.clientY);
    reorderAt(e.clientY);
  }
  function reorderAt(clientY){
    var item = drag.item, list = drag.list;
    var targetCenter = (clientY - drag.offset) + item.offsetHeight / 2;
    var children = Array.prototype.slice.call(list.children);
    var others = children.filter(function(x){ return x !== item; });
    var anchor = null;
    for (var i = 0; i < others.length; i++){
      var c = others[i].getBoundingClientRect().top + others[i].offsetHeight / 2;
      if(targetCenter < c){ anchor = others[i]; break; }
    }
    var currentIndex = children.indexOf(item);
    var targetIndex = (anchor === null) ? children.length : children.indexOf(anchor);
    if(targetIndex !== currentIndex){
      list.insertBefore(item, anchor);
      alignItem(clientY);
    }
  }
  function onPointerUp(){
    if(!drag) return;
    drag.item.classList.remove('disc-item--drag');
    drag.item.style.transform = '';
    drag = null;
  }

  document.querySelectorAll('.disc-item').forEach(function(item){
    item.setAttribute('tabindex', '0');
    item.setAttribute('draggable', 'false');
    item.addEventListener('pointerdown', function(e){ onPointerDown(e, item); });
    item.addEventListener('pointermove', onPointerMove);
    item.addEventListener('pointerup', onPointerUp);
    item.addEventListener('pointercancel', onPointerUp);
    item.addEventListener('keydown', function(e){
      var list = item.closest('.disc-list');
      var children = Array.prototype.slice.call(list.children);
      var idx = children.indexOf(item);
      if(e.key === 'ArrowUp' && idx > 0){
        e.preventDefault();
        list.insertBefore(item, children[idx - 1]);
      }
      if(e.key === 'ArrowDown' && idx < children.length - 1){
        e.preventDefault();
        list.insertBefore(item, children[idx + 1]);
      }
    });
  });

  /* ---------- share field ---------- */
  Array.prototype.slice.call(document.querySelectorAll('.copyfield__btn')).forEach(function(btn){
    btn.addEventListener('click', function(){
      var el = document.querySelector(btn.getAttribute('data-copy'));
      if(!el) return;
      var t = el.value;
      function done(){
        var label = btn.querySelector('.copyfield__btnText');
        if(label){ label.textContent = 'Copied!'; }
        setTimeout(function(){
          if(label) label.textContent = 'Copy';
        }, 1200);
      }
      if(navigator.clipboard && navigator.clipboard.writeText){
        navigator.clipboard.writeText(t).then(done, done);
      } else {
        var ta = document.createElement('textarea');
        ta.value = t;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        try { ta.select(); document.execCommand('copy'); } catch (ex) {}
        document.body.removeChild(ta);
        done();
      }
    });
  });

  setStep(0);
})();
