        res7 = await eval_js(cdp, '''(function(){
          return {
            first1: document.querySelector('#draggable-list1 > li').textContent.trim(),
            first2: document.querySelector('#draggable-list2 > li').textContent.trim(),
            list1types: Array.prototype.slice.call(document.querySelectorAll('#draggable-list1 > li')).map(function(x){return x.dataset.type;}),
            resultHidden: document.getElementById('discResult').hidden
          };
        })()''')
