        for m_ in logs:
            print('   ', m_.get('level'), m_.get('message'))
        assert not any(m_.get('level') == 'error' for m_ in logs), 'console errors!'

        reqs = cdp._events.get('Network.requestWillBeSent', [])
        print('10. network requestWillBeSent count:', len(reqs))
        for rq in reqs:
            print('   ', rq.get('type'), rq['request'].get('url'))
        assert all(rq['request'].get('url', '').startswith('file://') for rq in reqs)

        print('ALL SMOKE CHECKS PASSED')
        return {
            'list1_after_kb': res2,
            'list2_after_drag': res3,
            'score': res5['score'],
            'req_count': len(reqs),
        }
    finally:
