import asyncio, json, subprocess, time, sys
import urllib.request
import websockets

PORT = 9223
HERE = '/home/dp/MyProjects/disc/.tmpwork/disc-pi-ak2_84dq/run'

def get_page_ws(port):
    data = json.loads(urllib.request.urlopen(f'http://127.0.0.1:{port}/json').read().decode())
    pages = [p for p in data if p['type'] == 'page']
    return pages[0]['webSocketDebuggerUrl']

class CDP:
    def __init__(self, url):
        self.ws_url = url
        self.seq = 0
        self._pending = {}
        self._events = {}

    async def connect(self):
        ws = await __import__('websockets').connect(self.ws_url)
        self.ws = ws
        asyncio.create_task(self._reader())
        await self.call('Log.enable')
        await self.call('Page.enable')
        await self.call('Network.enable')
        await self.call('Input.enable')

    async def _reader(self):
        while True:
            try:
                msg = await self.ws.recv()
            except Exception:
                break
            r = json.loads(msg)
            if 'id' in r:
                self._pending[r['id']] = r
            elif 'event' in r:
                self._events.setdefault(r['event'], []).append(r.get('params'))

    async def call(self, method, params=None, timeout=30):
        self.seq += 1
        payload = {'id': self.seq, 'method': method}
        if params:
            payload['params'] = params
        await self.ws.send(json.dumps(payload, ensure_ascii=False))
        for _ in range(int(timeout * 100)):
            if self.seq in self._pending:
                r = self._pending.pop(self.seq)
                if 'error' in r:
                    raise RuntimeError(f'CDP error {method}: {r["error"]}')
                return r
            await asyncio.sleep(0.01)
        raise TimeoutError(f'CDP call {method} timed out')

async def eval_js(cdp, js):
    r = await cdp.call('Runtime.evaluate', {'expression': js, 'awaitPromise': False})
    return r['result'].get('value')

async def main():
    proc = subprocess.Popen(
        ['google-chrome', '--headless=new', '--no-sandbox', '--disable-gpu',
         '--disable-blink-features=AutomationControlled', f'--remote-debugging-port={PORT}',
         '--window-size=1300,950', 'about:blank'], stderr=subprocess.DEVNULL)
    ws_url = None
    for _ in range(25):
        time.sleep(0.3)
        try:
            ws_url = get_page_ws(PORT)
            break
        except Exception:
            continue
    if ws_url is None:
        proc.terminate()
        print('FAILED to connect to chrome', file=sys.stderr)
        return 2

    cdp = CDP(ws_url)
    try:
        await cdp.connect()
        await cdp.call('Page.navigate', {'url': f'file://{HERE}/index.html'})
        for _ in range(300):
            if 'Page.loadEventFired' in cdp._events:
                break
            await asyncio.sleep(0.05)
        else:
            print('FAIL: load event not fired')
            return 2
        await asyncio.sleep(0.2)

        res = await eval_js(cdp, '''(function(){
